      if($id){$stmt=$db->prepare('UPDATE products SET name=?,slug=?,category=?,sku=?,description=?,details=?,price=?,compare_price=?,stock=?,image=?,featured=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$stmt->execute([...$data,$id]);}else{$stmt=$db->prepare('INSERT INTO products(name,slug,category,sku,description,details,price,compare_price,stock,image,featured,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute($data);}flash('success',$id?'Product updated successfully.':'Product added successfully.');redirect('admin/?view=products');
