    if($action==='save_category'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Category name is required.');$description=trim($_POST['description']??'');$active=isset($_POST['active'])?1:0;if($id){$find=$db->prepare('SELECT name FROM categories WHERE id=?');$find->execute([$id]);$oldName=$find->fetchColumn();if(!$oldName)throw new RuntimeException('Category not found.');$db->beginTransaction();$db->prepare('UPDATE categories SET name=?,slug=?,description=?,active=? WHERE id=?')->execute([$name,slugify($name),$description,$active,$id]);$db->prepare('UPDATE products SET category=? WHERE category=?')->execute([$name,$oldName]);$db->commit();}else{$db->prepare('INSERT INTO categories(name,slug,description,active,sort_order) VALUES(?,?,?,?,?)')->execute([$name,slugify($name),$description,$active,(int)($_POST['sort_order']??50)]);}flash('success',$id?'Category updated.':'Category added.');redirect('admin/?view=categories');}
    if($action==='delete_category'){$id=(int)$_POST['id'];$find=$db->prepare('SELECT name FROM categories WHERE id=?');$find->execute([$id]);$name=$find->fetchColumn();$used=$db->prepare('SELECT COUNT(*) FROM products WHERE category=?');$used->execute([$name]);if((int)$used->fetchColumn()>0)throw new RuntimeException('Move or delete products in this category before deleting it.');$db->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('success','Category deleted.');redirect('admin/?view=categories');}
    if($action==='save_review'){$id=(int)($_POST['id']??0);$name=trim($_POST['customer_name']??'');$review=trim($_POST['review']??'');if(!$name||!$review)throw new RuntimeException('Customer name and review are required.');$data=[$name,trim($_POST['customer_type']??'Verified customer'),max(1,min(5,(int)($_POST['rating']??5))),$review,isset($_POST['active'])?1:0];if($id){$db->prepare('UPDATE reviews SET customer_name=?,customer_type=?,rating=?,review=?,active=? WHERE id=?')->execute([...$data,$id]);}else{$db->prepare('INSERT INTO reviews(customer_name,customer_type,rating,review,active,sort_order) VALUES(?,?,?,?,?,?)')->execute([...$data,50]);}flash('success',$id?'Review updated.':'Review added.');redirect('admin/?view=reviews');}
